  /**
   * Caching the same array a second time is rejected with an
   * IllegalArgumentException, because the array is already cached.
   */
  @Test(timeout = 4000)
  public void cacheArray_throwsWhenArrayAlreadyCached()  throws Throwable  {
      SegmentConstantPoolArrayCache cache = new SegmentConstantPoolArrayCache();
      String[] array = new String[7];

      cache.cacheArray(array);

      try {
        cache.cacheArray(array);
        fail("Expecting exception: IllegalArgumentException");

