      }
  }

  /**
   * arrayIsCached returns false when the CachedArray stored for an array key
   * reports a last known size that differs from the array's actual length.
   * Here a CachedArray built from a length-4 array is registered under a
   * length-7 array key, so the sizes disagree.
   */
  @Test(timeout = 4000)
  public void arrayIsCached_returnsFalseWhenCachedSizeDiffersFromArrayLength()  throws Throwable  {
      SegmentConstantPoolArrayCache cache = new SegmentConstantPoolArrayCache();
      String[] sevenElementArray = new String[7];
      String[] fourElementArray = new String[4];

      IdentityHashMap<String[], SegmentConstantPoolArrayCache.CachedArray> knownArrays = cache.knownArrays;
      SegmentConstantPoolArrayCache.CachedArray cachedArray = cache.new CachedArray(fourElementArray);
      knownArrays.put(sevenElementArray, cachedArray);
      assertEquals(4, cachedArray.lastKnownSize());

      boolean cached = cache.arrayIsCached(sevenElementArray);

      assertFalse(cached);
  }

